import itertools
from collections import deque

def neighbors(s, x, y):
    n = len(s)
    res = []
    Z = '0'*x; O = '1'*y
    for i in range(n - x - y + 1):
        if s[i:i+x] == Z and s[i+x:i+x+y] == O:
            res.append(s[:i] + O + Z + s[i+x+y:])
        if s[i:i+y] == O and s[i+y:i+y+x] == Z:
            res.append(s[:i] + Z + O + s[i+y+x:])
    return res

def components(n, x, y):
    states = [''.join(b) for b in itertools.product('01', repeat=n)]
    comp = {}
    cid = 0
    for s in states:
        if s in comp: continue
        dq = deque([s]); comp[s] = cid
        while dq:
            u = dq.popleft()
            for v in neighbors(u, x, y):
                if v not in comp:
                    comp[v] = cid; dq.append(v)
        cid += 1
    return comp

def feats(s, x, y):
    ones = s.count('1')
    # zero gaps mod y
    zg = []
    cur = 0
    for c in s:
        if c == '0':
            zg.append(cur); cur = 0
        else:
            cur += 1
    zg.append(cur)
    zg = tuple(g % y for g in zg)
    # one gaps mod x
    og = []
    cur = 0
    for c in s:
        if c == '1':
            og.append(cur); cur = 0
        else:
            cur += 1
    og.append(cur)
    og = tuple(g % x for g in og)
    return (ones, zg, og)

def check(n, x, y, verbose=False):
    comp = components(n, x, y)
    f = {s: feats(s, x, y) for s in comp}
    byf = {}
    for s in comp:
        byf.setdefault(f[s], set()).add(comp[s])
    bad_same = [(fs, cs) for fs, cs in byf.items() if len(cs) > 1]
    byc = {}
    for s in comp:
        byc.setdefault(comp[s], set()).add(f[s])
    bad_diff = [(c, fs) for c, fs in byc.items() if len(fs) > 1]
    ok = not bad_same and not bad_diff
    if verbose or not ok:
        print(f"n={n} x={x} y={y}: OK={ok}")
        for fs, cs in bad_same[:5]:
            print("  same feats, diff comps:", fs, sorted(cs))
            for c in sorted(cs):
                ex = [s for s in comp if comp[s]==c][:4]
                print("     comp", c, ex)
        for c, fs in bad_diff[:5]:
            print("  same comp, diff feats:", c, list(fs)[:4])
    return ok

if __name__ == '__main__':
    import sys
    fails = 0
    for n in range(1, 9):
        for x in range(1, n+1):
            for y in range(1, n+1):
                if x + y > n + 1:  # still test all
                    pass
                if not check(n, x, y):
                    fails += 1
    print("fails:", fails)
EOF
