import itertools
from collections import deque

def a_moves(s, x, y):
    n = len(s); res = []
    Z = '0'*x; O = '1'*y
    for i in range(n - x - y + 1):
        if s[i:i+x] == Z and s[i+x:i+x+y] == O:
            res.append(s[:i] + O + Z + s[i+x+y:])
    return res

def a_terminal(s, x, y):
    return not a_moves(s, x, y)

def nf_check(n, x, y, verbose=False):
    states = [''.join(b) for b in itertools.product('01', repeat=n)]
    bad = 0
    for s in states:
        seen = {s}
        dq = deque([s])
        terms = []
        if a_terminal(s, x, y): terms.append(s)
        while dq:
            u = dq.popleft()
            for v in a_moves(u, x, y):
                if v not in seen:
                    seen.add(v); dq.append(v)
                    if a_terminal(v, x, y): terms.append(v)
        if len(terms) != 1:
            bad += 1
            if verbose and bad <= 3:
                print(f"n={n} x={x} y={y} s={s}: {len(terms)} terminals: {terms[:6]}")
    if bad:
        print(f"n={n} x={x} y={y}: {bad}/{len(states)} strings with non-unique NF")
    return bad == 0

if __name__ == '__main__':
    allok = True
    for n in range(1, 11):
        for x in range(1, n+1):
            for y in range(1, n+1):
                if not nf_check(n, x, y):
                    allok = False
    print("ALL OK" if allok else "CONFLUENCE FAILURES")
