from bf import components
import itertools

def brute_nf(s, x, y):
    Z = '0'*x; O = '1'*y
    pat = Z + O
    while True:
        i = s.find(pat)
        if i < 0: break
        s = s[:i] + O + Z + s[i+x+y:]
    return s

def fast_nf(s, x, y):
    n = len(s)
    gaps = []
    cur = 0
    for ch in s:
        if ch == '0':
            gaps.append(cur); cur = 0
        else:
            cur += 1
    gaps.append(cur)
    k = len(gaps) - 1
    r = [g % y for g in gaps]
    c = [g // y for g in gaps]
    settle = [0]*(k+1)
    content = [0]*(k+1)
    last_nonempty = -1
    for i in range(k+1):
        if i < x:
            p = i
        else:
            if last_nonempty > i - x:
                p = i
            else:
                p = settle[i - x]
        settle[i] = p
        if c[i] > 0 and p != i:
            c[p] += c[i]
            c[i] = 0
        content[i] = r[i] + y * c[i]
        if content[i] > 0:
            last_nonempty = i
    parts = []
    for i in range(k+1):
        parts.append('1'*content[i])
        if i < k:
            parts.append('0')
    return ''.join(parts)

def check(n, x, y):
    comp = components(n, x, y)
    ok1 = ok2 = True
    bad1 = bad2 = 0
    strs = list(comp.keys())
    # equivalence check: same comp iff same brute_nf
    bynf = {}
    for s in strs:
        bynf.setdefault(brute_nf(s, x, y), set()).add(comp[s])
    for v in bynf.values():
        if len(v) > 1: bad1 += 1
    byc = {}
    for s in strs:
        byc.setdefault(comp[s], set()).add(brute_nf(s, x, y))
    for v in byc.values():
        if len(v) > 1: bad2 += 1
    ok1 = bad1 == 0 and bad2 == 0
    # fast_nf matches brute_nf
    mism = [s for s in strs if fast_nf(s, x, y) != brute_nf(s, x, y)]
    ok2 = not mism
    if not (ok1 and ok2):
        print(f"n={n} x={x} y={y}: nf-equiv-ok={ok1} fast-match={ok2}", 
              ("comps-per-nf:" + str([ (k, sorted(v)) for k,v in list(bynf.items())[:3] if len(v)>1]) if not ok1 else ""),
              (mism[:3] if not ok2 else ""))
    return ok1 and ok2

if __name__ == '__main__':
    fails = 0
    for n in range(1, 11):
        for x in range(1, n+1):
            for y in range(1, n+1):
                if not check(n, x, y):
                    fails += 1
        print("n", n, "done")
    print("fails:", fails)
