from bf import components

def brute_nf(s, x, y):
    Z = '0'*x; O = '1'*y
    pat = Z + O
    while True:
        i = s.find(pat)
        if i < 0: break
        s = s[:i] + O + Z + s[i+x+y:]
    return s

def fast_nf(s, x, y):
    gaps = []
    cur = 0
    for ch in s:
        if ch == '0':
            gaps.append(cur); cur = 0
        else:
            cur += 1
    gaps.append(cur)
    k = len(gaps) - 1
    rem = [g % y for g in gaps]
    chn = [g // y for g in gaps]
    content = [0]*(k+1)
    l1 = -1; c1 = -1; l2 = -1
    def note(j):
        nonlocal l1, c1, l2
        jc = j % x
        if j > l1:
            if c1 != jc:
                l2 = l1
            l1, c1 = j, jc
        elif j > l2 and jc != c1:
            l2 = j
    for i in range(k+1):
        cls = i % x
        if i < x:
            p = i
        else:
            if l1 >= 0 and c1 != cls:
                q = l1
            else:
                q = l2
            if q < 0:
                p = cls
            else:
                p = q + ((i - q) % x)
        ci = chn[i]
        if ci > 0:
            if p != i:
                content[p] += y * ci
                chn[i] = 0
                note(p)
        content[i] = rem[i] + y * chn[i]
        if content[i] > 0:
            note(i)
    parts = []
    for i in range(k+1):
        parts.append('1'*content[i])
        if i < k:
            parts.append('0')
    return ''.join(parts)

def check(n, x, y):
    comp = components(n, x, y)
    bad_nf = []
    bad_fast = []
    for s in comp:
        bn = brute_nf(s, x, y)
        fn = fast_nf(s, x, y)
        if fn != bn:
            bad_fast.append((s, bn, fn))
    # nf equivalence already verified; re-verify quickly here too
    bynf = {}
    for s in comp:
        bynf.setdefault(brute_nf(s, x, y), set()).add(comp[s])
    bad_eq = any(len(v) > 1 for v in bynf.values())
    byc = {}
    for s in comp:
        byc.setdefault(comp[s], set()).add(brute_nf(s, x, y))
    bad_eq2 = any(len(v) > 1 for v in byc.values())
    if bad_fast or bad_eq or bad_eq2:
        print(f"n={n} x={x} y={y}: fast-mismatches={len(bad_fast)} eq-fail={bad_eq or bad_eq2}")
        for t in bad_fast[:3]: print("   ", t)
        return False
    return True

