import random, itertools

LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def brute(vals):
    # pure recursion, no memoization: returns 'Takahashi'/'Aoki' with optimal play
    def rec(painted, red, blue, tscore, ascore, turn):
        # turn: 1=Takahashi to move, 2=Aoki to move
        for i in range(9):
            if painted >> i & 1:
                continue
            np = painted | (1 << i)
            nts, nas, nred, nblue = tscore, ascore, red, blue
            if turn == 1:
                nts += vals[i]; nred |= 1 << i
            else:
                nas += vals[i]; nblue |= 1 << i
            mask = nred if turn == 1 else nblue
            if any((mask & (1 << j)) and (mask & (1 << k)) and (mask & (1 << l)) for j,k,l in LINES):
                return 'Takahashi' if turn == 1 else 'Aoki'
            if np == 511:
                if nts > nas: return 'Takahashi'
                if nas > nts: return 'Aoki'
                return 'TIE'
            winner = rec(np, nred, nblue, nts, nas, 2 if turn == 1 else 1)
            if turn == 1 and winner == 'Takahashi':
                return 'Takahashi'
            if turn == 2 and winner == 'Aoki':
                return 'Aoki'
        return 'Aoki' if turn == 1 else 'Takahashi'  # mover loses if no winning move
    return rec(0, 0, 0, 0, 0, 1)

def memoized(vals):
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def mover_wins(state):
        red = sum(1 for c in state if c == 1); blue = sum(1 for c in state if c == 2)
        t_turn = (red == blue); me = 1 if t_turn else 2
        for i in range(9):
            if state[i]: continue
            ns = list(state); ns[i] = me; ns = tuple(ns)
            if any(all(ns[j] == me for j in ln) for ln in LINES):
                return True
            if all(ns):
                ts = sum(vals[j] for j in range(9) if ns[j] == 1)
                asx = sum(vals[j] for j in range(9) if ns[j] == 2)
                if (ts > asx) if t_turn else (asx > ts): return True
                continue
            if not mover_wins(ns): return True
        return False
    return 'Takahashi' if mover_wins((0,)*9) else 'Aoki'

