from collections import deque, defaultdict
from itertools import product
import sys

def invariant_key(s, x, y):
    ones = tuple(sorted(i % x for i, c in enumerate(s) if c == '1'))
    zeros = tuple(sorted(i % y for i, c in enumerate(s) if c == '0'))
    return (ones, zeros)

def classes_bfs(n, x, y, strs, adj_cache):
    if (n, x, y) in adj_cache:
        adj = adj_cache[(n, x, y)]
    else:
        adj = {}
        patA = '0'*x + '1'*y
        patB = '1'*y + '0'*x
        L = x + y
        for s in strs:
            nb = set()
            st = 0
            while True:
                i = s.find(patA, st)
                if i < 0: break
                nb.add(s[:i] + patB + s[i+L:])
                st = i + 1
            st = 0
            while True:
                i = s.find(patB, st)
                if i < 0: break
                nb.add(s[:i] + patA + s[i+L:])
                st = i + 1
            adj[s] = nb
        adj_cache[(n, x, y)] = adj
    seen = set()
    classes = []
    for s0 in strs:
        if s0 in seen: continue
        comp = []
        dq = deque([s0]); seen.add(s0)
        while dq:
            u = dq.popleft(); comp.append(u)
            for v in adj[u]:
                if v not in seen:
                    seen.add(v); dq.append(v)
        classes.append(frozenset(comp))
    return classes

def check(n):
    strs = [''.join(b) for b in product('01', repeat=n)]
    adj_cache = {}
    all_ok = True
    for x in range(1, n+1):
        for y in range(1, n+1):
            cls = classes_bfs(n, x, y, strs, adj_cache)
            part = defaultdict(set)
            for s in strs:
                part[invariant_key(s, x, y)].add(s)
            hyp = [frozenset(v) for v in part.values()]
            if sorted(cls, key=sorted) != sorted(hyp, key=sorted):
                all_ok = False
                print(f"MISMATCH n={n} x={x} y={y}")
                # show a diff sample
                setc = set(cls); seth = set(hyp)
                only_c = [c for c in cls if c not in seth][:2]
                only_h = [h for h in hyp if h not in setc][:2]
                for c in only_c: print("  bfs-only class:", sorted(c)[:6], "size", len(c))
                for h in only_h: print("  hyp-only class:", sorted(h)[:6], "size", len(h))
    print(f"n={n}: {'ALL MATCH' if all_ok else 'MISMATCHES FOUND'}")
    return all_ok

if __name__ == '__main__':
    ns = [int(a) for a in sys.argv[1:]] or list(range(1, 10))
    ok = all(check(n) for n in ns)
    print("OVERALL:", "OK" if ok else "FAIL")
