from fractions import Fraction

def brute(N, K):
    dist = {i: Fraction(0) for i in range(1, N+1)}
    dist[1] = Fraction(1)
    stay = 1 - Fraction(2*(N-1), N*N)
    move = Fraction(2, N*N)
    for _ in range(K):
        nd = {i: Fraction(0) for i in range(1, N+1)}
        for i, p in dist.items():
            nd[i] += p * stay
            for j in range(1, N+1):
                if j != i:
                    nd[j] += p * move
        dist = nd
    return sum(i * p for i, p in dist.items())

def formula(N, K):
    s = 1 - Fraction(2, N)
    p1 = Fraction(1, N) + Fraction(N-1, N) * s**K
