from itertools import permutations, product
MOD = 998244353

def brute(n, s):
    """direct strong connectivity check over all matchings; also cross-checks orbit criterion"""
    blacks = [i for i,c in enumerate(s) if c=='B']   # 0-indexed
    whites = [i for i,c in enumerate(s) if c=='W']
    assert len(blacks)==len(whites)==n
    cnt = 0
    allv = set(range(2*n))
    for perm in permutations(whites):
        sigma = dict(zip(blacks, perm))
        # orbit check (0-indexed): m starts at 0 (vertex 1). Vertex 1 must be black.
        ok = True
        if 0 not in sigma:
            ok = False
        else:
            m = 0
            while True:
                cands = [sigma[b] for b in blacks if b <= m]
                if not cands:
                    ok = False; break
                nm = max(cands)
                if nm >= 2*n-1:
                    break
                if nm <= m:
                    ok = False; break
                m = nm
        # direct strong connectivity
        adj = {i: [] for i in range(2*n)}
        for i in range(2*n-1):
            adj[i].append(i+1)
        for b, w in sigma.items():
            adj[w].append(b)
        def reach(src):
            st=[src]; seen={src}
            while st:
                v=st.pop()
                for u in adj[v]:
                    if u not in seen:
                        seen.add(u); st.append(u)
            return seen
        sc = all(reach(v)==allv for v in allv)
        assert sc == ok, (n, s, perm, sc, ok)
        if sc: cnt += 1
    return cnt

def formula(n, s):
    """inclusion-exclusion DP over stuck points with d(m)<=0"""
    d = 0
    pts = []  # (prefix length m, d(m)), 1-indexed prefix lengths, m<2n
    for i, c in enumerate(s):
        d += 1 if c=='B' else -1
        if d <= 0 and i+1 < 2*n:
            pts.append((i+1, d))
    pts.append((2*n, 0))
    K = len(pts)
    Bcount_at = [sum(1 for c in s[:m] if c=='B') for (m, dd) in pts]
    def F(beta, omega):
        r = 1
        for k in range(beta):
            r = r * (omega - k) % MOD
        return r
    dp = [0]*K
    dp[0] = -1
    for i in range(1, K):
        tot = 0
        for j in range(i):
            beta = Bcount_at[i] - Bcount_at[j]
            omega = beta - (pts[i][1] - pts[j][1])
            tot = (tot + dp[j] * (-1) * F(beta, omega)) % MOD
        dp[i] = tot
    return (-dp[K-1]) % MOD

if __name__ == '__main__':
    for n in range(1, 5):
        for sbits in product('WB', repeat=2*n):
            s = ''.join(sbits)
            if sbits.count('B') != n: continue
            b = brute(n, s)
            f = formula(n, s)
            if b != f:
                print("MISMATCH", n, s, b, f); raise SystemExit
    print("all consistent for n<=4")
