from itertools import permutations, product
from math import factorial
MOD = 998244353

def brute(n, s):
    blacks = [i for i,c in enumerate(s) if c=='B']
    whites = [i for i,c in enumerate(s) if c=='W']
    assert len(blacks)==len(whites)==n
    cnt = 0
    allv = set(range(2*n))
    for perm in permutations(whites):
        sigma = dict(zip(blacks, perm))
        ok = True
        if 0 not in sigma:
            ok = False
        else:
            m = 0
            while True:
                cands = [sigma[b] for b in blacks if b <= m]
                if not cands:
                    ok = False; break
                nm = max(cands)
                if nm >= 2*n-1:
                    break
                if nm <= m:
                    ok = False; break
                m = nm
        adj = {i: [] for i in range(2*n)}
        for i in range(2*n-1):
            adj[i].append(i+1)
        for b, w in sigma.items():
            adj[w].append(b)
        def reach(src):
            st=[src]; seen={src}
            while st:
                v=st.pop()
                for u in adj[v]:
                    if u not in seen:
                        seen.add(u); st.append(u)
            return seen
        sc = all(reach(v)==allv for v in allv)
        assert sc == ok, (n, s, perm, sc, ok)
        if sc: cnt += 1
    return cnt

def formula(n, s):
    d = 0
    pts = []   # (m, d(m)) for m<2n with d<=0
    for i, c in enumerate(s):
        d += 1 if c=='B' else -1
        if d <= 0 and i+1 < 2*n:
            pts.append((i+1, d))
    K = len(pts)
    Bc = [sum(1 for c in s[:m] if c=='B') for (m, dd) in pts]
    Dc = [dd for (m, dd) in pts]
    def F(beta, omega):
        r = 1
        for k in range(beta):
            r = r * (omega - k) % MOD
        return r
    # A[i] = sum over S subset of stuck-pts[0..i-1] of (-1)^|S| * prod F(blocks)
    A = [0]*(K+1)
    A[0] = 1
    for i in range(1, K+1):
        if i <= K-1:
            Bi, Di = Bc[i], Dc[i]
        else:
            Bi, Di = None, None
        tot = 0
        for j in range(i):
            if j < K:
                Bj, Dj = Bc[j], Dc[j]
            else:
                continue
            if i <= K-1:
                beta = Bi - Bj
                omega = beta - Di
            else:
                continue
            tot = (tot + A[j] * (-1) * F(beta, omega)) % MOD
        if i <= K-1:
            A[i] = tot
        else:
            A[i] = 0  # placeholder, final term handled below
    ans = 0
    prevB = [0] + Bc   # B_{i-1} for i=0..K
    for i in range(0, K+1):
        ans = (ans + A[i] * factorial(n - prevB[i])) % MOD
    return ans % MOD

if __name__ == '__main__':
    for n in range(1, 5):
        for sbits in product('WB', repeat=2*n):
            s = ''.join(sbits)
            if sbits.count('B') != n: continue
            b = brute(n, s)
            f = formula(n, s)
            if b != f:
                print("MISMATCH", n, s, b, f); raise SystemExit
    print("all consistent for n<=4")
