import itertools, math
from functools import lru_cache

def lis(seq):
    # strict LIS length, O(n^2) fine for small
    n=len(seq); best=[0]*n; ans=0
    for i in range(n):
        best[i]=1
        for j in range(i):
            if seq[j]<seq[i] and best[j]+1>best[i]: best[i]=best[j]+1
        ans=max(ans,best[i])
    return ans

def lds(seq):
    return lis([-x for x in seq])

@lru_cache(maxsize=None)
def fsyt(rows):
    # number of SYT of shape given as tuple rows (partition)
    N=sum(rows)
    # hook length formula
    lam={}
    # column heights
    H=1
    for i,li in enumerate(rows):
        for j in range(li):
            right=li-j-1
            below=sum(1 for k in range(i+1,len(rows)) if rows[k]>j)
            H*= (right+below+1)
    return math.factorial(N)//H

def frect(a,b):
    return fsyt(tuple([a]*b))

def brute(A,B):
    N=A*B-1
    validP=set(); pairs=0
    for P in itertools.permutations(range(1,N+1)):
