import itertools, math
from functools import lru_cache
import bisect

def lis_len(seq):
    tails=[]
    for x in seq:
        i=bisect.bisect_left(tails,x)
        if i==len(tails): tails.append(x)
        else: tails[i]=x
    return len(tails)

def lds_len(seq):
    return lis_len([-x for x in seq])

@lru_cache(maxsize=None)
def fsyt(rows):
    N=sum(rows); H=1
    for i,li in enumerate(rows):
        for j in range(li):
            below=sum(1 for k in range(i+1,len(rows)) if rows[k]>j)
            H*= (li-j-1+below+1)
    return math.factorial(N)//H

def frect(a,b): return fsyt(tuple([a]*b))

def gen_syt(rows):
    """generate all SYT of shape rows (tuple), as tuple of rows (lists)"""
    B=len(rows); A=max(rows)
    cells=[(i,j) for i in range(B) for j in range(rows[i])]
    N=len(cells)
    T={}
    res=[]
    def rec(k):
        if k==N:
            res.append(tuple(tuple(T[(i,j)] for j in range(rows[i])) for i in range(B)))
            return
        for (i,j) in cells:
            if (i,j) in T: continue
            if i>0 and (i-1,j) not in T: continue
            if j>0 and (i,j-1) not in T: continue
            if i>0 and T[(i-1,j)]>k: continue   # not needed since we fill in order but fine
            # pruning: must be > left and up neighbors (auto since we assign increasing values in order)
            T[(i,j)]=k+1
            rec(k+1)
            del T[(i,j)]
