from functools import lru_cache

def brute(n, cards):
    full = (1<<n)-1
    # match bitmasks
    adj = [0]*n
    for i in range(n):
        for j in range(n):
            if i!=j and (cards[i][0]==cards[j][0] or cards[i][1]==cards[j][1]):
                adj[i] |= 1<<j
    @lru_cache(maxsize=None)
    def win(mask):
        if mask==0: return False
        m = mask
        while m:
            ib = m & -m; m ^= ib
            i = ib.bit_length()-1
            cand = mask & adj[i] & m  # j > i in mask matching i
            while cand:
                jb = cand & -cand; cand ^= jb
                if not win(mask ^ ib ^ jb):
                    return True
        return False
    return 'Takahashi' if win(full) else 'Aoki'

