"""
Solution implementation.

Determine if square N is reachable from square 1 by jumps of size in [a, b],
never landing on a square covered by any bad interval.

Algorithm (n can be up to 1e12, so we never iterate over all squares):
- Merge bad intervals; split [1, n] into maximal "good blocks".
- Sweep the line while maintaining a b-bit sliding window (bit t of `window`
  equals reachability of square (cur - t)) so that landings from up to b
  squares behind (possibly skipping short bad gaps / tiny blocks) are handled.
- For each good block:
    * entries = squares in the first b positions of the block reachable by a
      jump from a reachable square behind the block (plus square 1 if L == 1).
    * if a < b: once a single square x is reachable, the "generations"
      [x + k*a, x + k*b] merge into one contiguous run from
      x + ceil((a-1)/(b-a))*a onward, so everything from that point to the end
      of the block is reachable; the (short) prefix before that point is
      simulated exactly.
    * if a == b: reachability inside a block is purely by residue classes
      modulo a of the entry squares (plus the entry squares themselves).
"""
from typing import List, Tuple


def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    if n <= 1:
        return True

    # --- normalize the bad intervals (clamp to [1, n], sort, merge) ---
    ivs = []
    for l, r in bad_intervals:
        lo, hi = max(1, l), min(n, r)
        if lo <= hi:
            ivs.append((lo, hi))
    ivs.sort()
    merged: List[List[int]] = []
    for lo, hi in ivs:
        if merged and lo <= merged[-1][1] + 1:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # target square must be usable
    for lo, hi in merged:
        if lo <= n <= hi:
            return False

    # --- maximal good blocks ---
    blocks = []
    prev = 0
    for lo, hi in merged:
        if lo - 1 >= prev + 1:
            blocks.append((prev + 1, lo - 1))
        prev = hi
    if prev + 1 <= n:
        blocks.append((prev + 1, n))
    if blocks[0][0] != 1:
        # square 1 is where we start; even if it is "bad", we stand on it
        blocks.insert(0, (1, 1))

    mask = (1 << b) - 1
    a_off = a - 1
    span_mask = (1 << (b - a + 1)) - 1  # bits a-1 .. b-1 of the window
    kk = -(-(a - 1) // (b - a)) if a < b else 0  # ceil((a-1)/(b-a))

    window = 0  # bit t  <=>  square (cur - t) is reachable, cur = L - 1

    for L, R in blocks:
        is_last = (R == n)

        # --- entries into the block (only the first b positions can be entered) ---
        E = set()
        if L == 1:
            E.add(1)  # starting square
        hi_j = min(R, L + b - 1)
        for j in range(L, hi_j + 1):
            d = j - L
            lo_t = a_off - d
            if lo_t < 0:
                lo_t = 0
            hi_t = b - 1 - d
            if lo_t <= hi_t and (window >> lo_t) & ((1 << (hi_t - lo_t + 1)) - 1):
                E.add(j)

        if not E:
            if is_last:
                return False
            length = R - L + 1
            if length >= b:
                window = 0
            else:
                window = (window << length) & mask
            continue

        tail_bits = 0  # bit t <=> square (R - t) reachable
        if a == b:
            residues = set(e % a for e in E)
            thresh = L + a
            for t in range(b):
                p = R - t
                if p < L:
                    continue
                if p >= thresh:
                    if p % a in residues:
                        tail_bits |= 1 << t
                else:
                    if p in E:
                        tail_bits |= 1 << t
            if is_last:
                return (R >= thresh and R % a in residues) or (R in E)
        else:
            s = max(E) + kk * a  # everything >= s inside the block is reachable
            sim_hi = min(R, s - 1)
            entry_bits = 0
            for e in E:
                entry_bits |= 1 << (e - L)
            sim_bits = 0
            w = window
            for idx in range(sim_hi - L + 1):
                nw = (entry_bits >> idx) & 1
                if not nw and ((w >> a_off) & span_mask):
                    nw = 1
                sim_bits |= nw << idx
                w = ((w << 1) | nw) & mask
            for t in range(b):
                p = R - t
                if p < L:
                    continue
                if p >= s:
                    tail_bits |= 1 << t
                elif (sim_bits >> (p - L)) & 1:
                    tail_bits |= 1 << t
            if is_last:
                if R >= s:
                    return True
                return bool((sim_bits >> (R - L)) & 1)

        length = R - L + 1
        if length >= b:
            carry = 0
        else:
            carry = (window << length) & mask
        window = (tail_bits | carry) & mask

    return False
