from collections import deque

def strongly_connected(n, s, pairing):
    m = 2*n
    radj = [[] for _ in range(m+1)]  # reverse edges
    for i in range(1, m):
        radj[i+1].append(i)
    for w, b in pairing:
        radj[b].append(w)
    # vertices that can reach 1 = reachable from 1 in reverse graph
    seen = {1}; dq = deque([1])
    while dq:
        u = dq.popleft()
        for v in radj[u]:
            if v not in seen:
                seen.add(v); dq.append(v)
    return len(seen) == m

def brute(n, s):
    whites = [i+1 for i,c in enumerate(s) if c=='W']
    blacks = [i+1 for i,c in enumerate(s) if c=='B']
    cnt = 0
    for perm in itertools.permutations(blacks):
        if strongly_connected(n, s, list(zip(whites, perm))):
            cnt += 1
    return cnt

def char_condition(n, s):
    m = 2*n
    if s[0] != 'B' or s[-1] != 'W':
        return 0
    cnt = 0
    whites = [i+1 for i,c in enumerate(s) if c=='W']
    blacks = [i+1 for i,c in enumerate(s) if c=='B']
    for perm in itertools.permutations(blacks):
        ok = True
        sufmin = perm[n-1]
        for j in range(n-1, 0, -1):
            if sufmin > whites[j-1]:
                ok = False; break
            sufmin = min(sufmin, perm[j-1])
        if ok:
            cnt += 1
    return cnt

