"""
Solution implementation.

Determine whether square N is reachable from square 1 with jumps in [a, b],
landing only on good squares (squares not covered by any bad interval).

Key observations
----------------
* n can be up to 1e12, so we work on "good segments" (maximal runs of good
  squares) instead of individual squares.
* The set of total distances achievable with k jumps (each in [a, b]) is
  exactly every integer in [k*a, k*b].  Hence the set T of all achievable
  distances (with any positive number of jumps) is
        T = union_{k>=1} [k*a, k*b]
  which is a union of few intervals: for a < b these intervals merge into a
  single ray [K*a, inf) after at most a <= 20 steps; for a == b it is the
  arithmetic progression {a, 2a, 3a, ...}.
* Inside a single good segment (no obstacles), a square w is reachable from a
  set of entry squares E iff  w in E  or  exists x in E with (w - x) in T.
* Only the last b squares of a segment can jump over the following bad block
  into a later segment, so we only have to track reachable squares inside a
  window of b squares at the end of each segment.  Entries of a segment
  always land within its first b-1 squares, so the per-segment state is small
  (at most b-1 squares).
"""

from typing import List, Tuple
from bisect import bisect_right


def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    # ---------- 1. normalize the bad intervals (sort, clip, merge) ----------
    ivs = []
    for l, r in bad_intervals:
        if l > r:
            l, r = r, l
        if l < 1:
            l = 1
        if r > n:
            r = n
        if l <= r:
            ivs.append((l, r))
    ivs.sort()

    merged: List[Tuple[int, int]] = []
    for l, r in ivs:
        if merged and l <= merged[-1][1] + 1:
            if r > merged[-1][1]:
                merged[-1] = (merged[-1][0], r)
        else:
            merged.append((l, r))

    def is_bad(x: int) -> bool:
        lo, hi = 0, len(merged) - 1
        while lo <= hi:
            mid = (lo + hi) >> 1
            l, r = merged[mid]
            if x < l:
                hi = mid - 1
            elif x > r:
                lo = mid + 1
            elif x > r:
                lo = mid + 1
            else:
                return True
        return False

    if n <= 1:
        return not is_bad(1)
    # We must be able to stand on square 1 and to land on square n.
    if is_bad(1) or is_bad(n):
        return False

    # ---------- 2. structure of the jump-sum semigroup T ----------
    # T = union_{k>=1} [k*a, k*b]; membership test for a distance d >= 1.
    if a == b:
        step = a

        def in_T(d: int) -> bool:
            return d > 0 and d % step == 0
    else:
        # K = smallest k with [k*a, k*b] touching [(k+1)*a, (k+1)*b]
        K = 1
        while (K + 1) * a > K * b + 1:
            K += 1
        ray_start = K * a          # T contains [K*a, inf)
        last_finite_k = K - 1      # T contains the disjoint blocks [k*a, k*b]

        def in_T(d: int) -> bool:
            if d <= 0:
                return False
            if d >= ray_start:
                return True
            lo = -(-d // b)        # ceil(d / b)
            hi = d // a
            if hi > last_finite_k:
                hi = last_finite_k
            return lo <= hi

    # ---------- 3. good segments ----------
    segs = []
    prev = 0
    for l, r in merged:
        if l - 1 >= prev + 1:
            segs.append((prev + 1, l - 1))
        prev = r
    if n >= prev + 1:
        segs.append((prev + 1, n))
    starts = [s for s, _ in segs]

    idx = bisect_right(starts, 1) - 1
    if idx < 0 or not (segs[idx][0] <= 1 <= segs[idx][1]):
        return False

    # ---------- 4. sweep over segments ----------
    # pending[t] = set of reachable entry squares of segment t (<= b-1 values)
    pending = {idx: {1}}
    num_segs = len(segs)

    for i in range(idx, num_segs):
        entries = pending.pop(i, None)
        if not entries:
            continue
        s, e = segs[i]

        # squares of this segment that can still jump into a later segment
        wlo = e - b + 1
        if wlo < s:
            wlo = s

        exits = []
        for w in range(wlo, e + 1):
            if w in entries:
                exits.append(w)
                continue
            for x in entries:
                if in_T(w - x):
                    exits.append(w)
                    break

        # forward reachable landings into later segments
        for x in exits:
            y_hi = x + b
            if y_hi > n:
                y_hi = n
            for y in range(x + a, y_hi + 1):
                t = bisect_right(starts, y) - 1
                if t > i and y <= segs[t][1]:
                    pending.setdefault(t, set()).add(y)

        # the last segment is the only one containing square n
        if e == n:
            if n in entries:
                return True
            for x in entries:
                if in_T(n - x):
                    return True
            return False

    return False
