from collections import deque

def brute(n, m, a, b, bad_intervals):
    bad = set()
    for l, r in bad_intervals:
        for j in range(max(1, l), min(n, r) + 1):
            bad.add(j)
    if 1 in bad or n in bad:
        return False
    reach = {1}
    dq = deque([1])
    while dq:
        x = dq.popleft()
        if x == n:
            return True
        for i in range(a, b + 1):
            y = x + i
            if y <= n and y not in bad and y not in reach:
                reach.add(y)
                dq.append(y)
    return n in reach
