"""Prototype: minimum walk cover via Dilworth width of condensation of line digraph."""
from collections import deque


def solve(n, product_names):
    edges = []
    seen = set()
    for s in product_names:
        if len(s) < 2:
            continue
        a, b = ord(s[0]) - 65, ord(s[1]) - 65
        if (a, b) in seen:
            continue
        seen.add((a, b))
        edges.append((a, b))
    m = len(edges)
    if m == 0:
        return 0

    by_tail = [[] for _ in range(26)]
    for j, (t, h) in enumerate(edges):
        by_tail[t].append(j)
    succ = [by_tail[h] for (t, h) in edges]

    # Kosaraju SCC on line digraph
    visited = [False] * m
    order = []
    for s in range(m):
        if visited[s]:
            continue
        stack = [(s, iter(succ[s]))]
        visited[s] = True
        while stack:
            u, it = stack[-1]
            advanced = False
            for w in it:
                if not visited[w]:
                    visited[w] = True
                    stack.append((w, iter(succ[w])))
                    advanced = True
                    break
            if not advanced:
                order.append(u)
                stack.pop()
    pred = [[] for _ in range(m)]
    for u in range(m):
        for w in succ[u]:
            pred[w].append(u)
    comp = [-1] * m
    k = 0
    for u in reversed(order):
        if comp[u] != -1:
            continue
        stack = [u]
        comp[u] = k
        while stack:
            x = stack.pop()
            for y in pred[x]:
                if comp[y] == -1:
                    comp[y] = k
                    stack.append(y)
        k += 1

    cadj = [set() for _ in range(k)]
    for u in range(m):
        for w in succ[u]:
            if comp[w] != comp[u]:
                cadj[comp[u]].add(comp[w])

    indeg = [0] * k
    for u in range(k):
        for w in cadj[u]:
            indeg[w] += 1
    topo = [u for u in range(k) if indeg[u] == 0]
    i = 0
    while i < len(topo):
        u = topo[i]
        i += 1
        for w in cadj[u]:
            indeg[w] -= 1
            if indeg[w] == 0:
                topo.append(w)

    reach = [0] * k
    for u in reversed(topo):
        r = 1 << u
        for w in cadj[u]:
            r |= reach[w]
        reach[u] = r

    adjL = []
    for u in range(k):
        r = reach[u] & ~(1 << u)
        lst = []
        while r:
            b = r & (-r)
            lst.append(b.bit_length() - 1)
            r ^= b
        adjL.append(lst)

    # Hopcroft-Karp
    matchL = [-1] * k
    matchR = [-1] * k
    matching = 0
    while True:
        dist = [-1] * k
        q = deque()
        for u in range(k):
            if matchL[u] == -1:
                dist[u] = 0
                q.append(u)
        free_reached = False
        while q:
            u = q.popleft()
            for v in adjL[u]:
                w = matchR[v]
                if w == -1:
                    free_reached = True
                elif dist[w] == -1:
                    dist[w] = dist[u] + 1
                    q.append(w)
        if not free_reached:
            break

        def dfs(u, _dist=dist):
            for v in adjL[u]:
                w = matchR[v]
                if w == -1 or (_dist[w] == _dist[u] + 1 and dfs(w)):
                    matchL[u] = v
                    matchR[v] = u
                    return True
            _dist[u] = -1
            return False

        for u in range(k):
            if matchL[u] == -1 and dfs(u):
                matching += 1
    return k - matching


