"""Cross-validate the Dilworth-width model against brute force + verify constructed walks."""
import random, itertools
from collections import deque
import sys
sys.path.insert(0, '/agent/scratch')
from model import solve


def edges_of(names):
    return [(ord(s[0]) - 65, ord(s[1]) - 65) for s in names]


def reach_pairs(edges):
    """Return (comp adjacency-free) pairwise reachability on edges of line digraph as dict of sets."""
    m = len(edges)
    by_tail = [[] for _ in range(26)]
    for j, (t, h) in enumerate(edges):
        by_tail[t].append(j)
    succ = [by_tail[h] for (t, h) in edges]
    # reachability via BFS per node
    reach = [set() for _ in range(m)]
    for s in range(m):
        dq = deque([s])
        seen = [False] * m
        seen[s] = True
        while dq:
            u = dq.popleft()
            for w in succ[u]:
                reach[s].add(w)
                if not seen[w]:
                    seen[w] = True
                    dq.append(w)
    return succ, reach


def brute_min_walks(edges):
    """Minimum number of blocks in a partition of edges where each block is a set of
    pairwise-comparable edges (realizable as one walk)."""
    m = len(edges)
    if m == 0:
        return 0
    _, reach = reach_pairs(edges)
    # comparable[a][b]: a <=* b
    best = m
    # enumerate set partitions of range(m)
    def partitions(elements):
        if not elements:
            yield []
            return
        first, rest = elements[0], elements[1:]
        for p in partitions(rest):
            for i in range(len(p)):
                p[i] = p[i] + [first]
                yield p
                p[i] = p[i][:-1]
            yield p + [[first]]
    for p in partitions(list(range(m))):
        ok = True
        cnt = 0
        for block in p:
            cnt += 1
            if cnt >= best:
                ok = False
                break
            bl = list(block)
            for a, b in itertools.combinations(bl, 2):
                if a not in reach[b] and b not in reach[a]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            best = min(best, cnt)
    return best


def construct_walks(names):
    """Build actual NG strings from chain decomposition of condensation; return list of strings."""
    edges = edges_of(names)
    m = len(edges)
    by_tail = [[] for _ in range(26)]
    for j, (t, h) in enumerate(edges):
        by_tail[t].append(j)
    succ = [by_tail[h] for (t, h) in edges]
    # SCC via Kosaraju (same as model)
    visited = [False] * m
    order = []
    for s in range(m):
        if visited[s]:
            continue
        stack = [(s, iter(succ[s]))]
        visited[s] = True
        while stack:
            u, it = stack[-1]
            adv = False
            for w in it:
                if not visited[w]:
                    visited[w] = True
                    stack.append((w, iter(succ[w])))
                    adv = True
                    break
            if not adv:
                order.append(u)
                stack.pop()
    pred = [[] for _ in range(m)]
    for u in range(m):
        for w in succ[u]:
            pred[w].append(u)
    comp = [-1] * m
    k = 0
    for u in reversed(order):
        if comp[u] != -1:
            continue
        st = [u]; comp[u] = k
        while st:
            x = st.pop()
            for y in pred[x]:
                if comp[y] == -1:
                    comp[y] = k
                    st.append(y)
        k += 1
    cadj = [set() for _ in range(k)]
    for u in range(m):
        for w in succ[u]:
            if comp[w] != comp[u]:
                cadj[comp[u]].add(comp[w])
    indeg = [0] * k
    for u in range(k):
        for w in cadj[u]:
            indeg[w] += 1
    topo = [u for u in range(k) if indeg[u] == 0]
    i = 0
    while i < len(topo):
        u = topo[i]; i += 1
        for w in cadj[u]:
            indeg[w] -= 1
            if indeg[w] == 0:
                topo.append(w)
    reach = [0] * k
    for u in reversed(topo):
        r = 1 << u
        for w in cadj[u]:
            r |= reach[w]
        reach[u] = r
    # min chain cover via matching (Kuhn, small)
    adjL = []
    for u in range(k):
        r = reach[u] & ~(1 << u)
        lst = []
        while r:
            b = r & (-r); lst.append(b.bit_length() - 1); r ^= b
        adjL.append(lst)
    matchR = [-1] * k
    def try_aug(u, vis):
        for v in adjL[u]:
            if vis[v]:
                continue
            vis[v] = True
            if matchR[v] == -1 or try_aug(matchR[v], vis):
                matchR[v] = u
                return True
        return False
    for u in range(k):
        try_aug(u, [False] * k)
    # successor structure: comp-successor via matchR (v -> u means u before v)
    nxt = {}   # comp u -> comp v where u matched to v (u immediately precedes v in chain)
    for v, u in enumerate(matchR):
        if u != -1:
            nxt[u] = v
    starts = [u for u in range(k) if u not in set(nxt.values())]
    # For each chain of comps, build a single walk covering all edges of each comp in order.
    # For comp c in isolation, build closed-ish walk: order edges of comp: start edge s,
    # then traverse: we need a walk that visits all edges of comp and can start at any chosen edge.
    # Because all edges of one comp are mutually reachable, we can greedily chain.
    def walk_for_comp(c, first_edge=None):
        es = [i for i in range(m) if comp[i] == c]
        if first_edge is not None:
            es.remove(first_edge)
            es = [first_edge] + es
        seq = [es[0]]
        used = {es[0]}
        # repeatedly append an edge reachable from current head
        while len(used) < len(es):
            cur = seq[-1]
            head = edges[cur][1]
            # find unused edge starting at head
            nxt_e = None
            for cand in by_tail[head]:
                if cand not in used and comp[cand] == c:
                    nxt_e = cand
                    break
            if nxt_e is None:
                # hop: BFS from head to a tail of an unused comp-edge
                found = None
                dq = deque([head]); par = {head: None}; seenv = {head}
                while dq and found is None:
                    x = dq.popleft()
                    for cand in by_tail[x]:
                        if cand not in used and comp[cand] == c:
                            found = (x, cand); break
                        # continue BFS through edges
                    if found is None:
                        for cand in by_tail[x]:
                            y = edges[cand][1]
                            if y not in seenv:
                                seenv.add(y); par[y] = (x, cand); dq.append(y)
                if found is None:
                    return None
                x, cand = found
                # reconstruct path of edges from head to x
                path_edges = []
                yy = x
                while par[yy] is not None:
                    px, pe = par[yy]
                    path_edges.append(pe)
                    yy = px
                path_edges.reverse()
                for pe in path_edges:
                    seq.append(pe); used.add(pe)
                seq.append(cand); used.add(cand)
            else:
                seq.append(nxt_e); used.add(nxt_e)
        return seq
    chains = []
    for s in starts:
        chain = []
        u = s
        while True:
            chain.append(u)
            if u not in nxt:
                break
            u = nxt[u]
        chains.append(chain)
    strings = []
    for chain in chains:
        seq = []
        for idx, c in enumerate(chain):
            es = [i for i in range(m) if comp[i] == c]
            if idx == 0:
                part = walk_for_comp(c, None)
            else:
                head_letter = edges[seq[-1]][1]
                entry = None
                for cand in by_tail[head_letter]:
                    if comp[cand] == c:
                        entry = cand
                        break
                if entry is None:
                    return None  # shouldn't happen
                part = walk_for_comp(c, entry)
            if part is None:
                return None
            for e in part:
                if not seq or edges[seq[-1]][1] == edges[e][0]:
                    seq.append(e)
                else:
                    # bridge via BFS outside comps (intermediate edges allowed, they get covered too)
                    return None
        # build string
        s = chr(65 + edges[seq[0]][0])
        for e in seq:
            s += chr(65 + edges[e][1])
        strings.append(s)
    return strings


def verify(names, strings):
    edges = set(edges_of(names))
    for s in strings:
        for i in range(len(s) - 1):
            if (ord(s[i]) - 65, ord(s[i+1]) - 65) not in edges:
                return False
    covered = set()
    for s in strings:
        for i in range(len(s) - 1):
            covered.add((ord(s[i]) - 65, ord(s[i+1]) - 65))
    return covered == edges


random.seed(7)
bad = 0
for trial in range(400):
    alpha = random.choice([2, 3, 4, 6])
    m = random.randint(1, 6)
    names = [chr(65 + random.randrange(alpha)) + chr(65 + random.randrange(alpha)) for _ in range(m)]
    names = list(dict.fromkeys(names))
    model_ans = solve(len(names), names)
    edges = edges_of(names)
    bf = brute_min_walks(edges)
    if model_ans != bf:
        bad += 1
        print('MISMATCH', names, 'model', model_ans, 'brute', bf)
        if bad > 5:
            break
print('brute-force cross-check done, mismatches =', bad)

# verify constructed walks are valid & cover all, and count matches model
random.seed(11)
bad2 = 0
for trial in range(300):
    alpha = random.choice([2, 3, 5, 8])
    m = random.randint(1, 9)
    names = [chr(65 + random.randrange(alpha)) + chr(65 + random.randrange(alpha)) for _ in range(m)]
    names = list(dict.fromkeys(names))
    strings = construct_walks(names)
    model_ans = solve(len(names), names)
    if strings is None:
