"""Constructive validation: build actual NG strings, verify validity + coverage + count."""
import random, sys
from collections import deque
sys.path.insert(0, '/agent/scratch')
from model import solve


def edges_of(names):
    return [(ord(s[0]) - 65, ord(s[1]) - 65) for s in names]


def build(names):
    edges = edges_of(names)
    m = len(edges)
    by_tail = [[] for _ in range(26)]
    for j, (t, h) in enumerate(edges):
        by_tail[t].append(j)
    succ = [by_tail[h] for (t, h) in edges]
    # BFS in line digraph from edge a to edge b -> edge sequence (walk)
    def path_lg(a, b):
        if a == b:
            return [a]
        par = {a: None}
        dq = deque([a])
        while dq:
            u = dq.popleft()
            for w in succ[u]:
                if w not in par:
                    par[w] = u
                    if w == b:
                        seq = [b]
                        while par[seq[-1]] is not None:
                            seq.append(par[seq[-1]])
                        return seq[::-1]
                    dq.append(w)
        return None
    # SCC via Kosaraju
    visited = [False] * m
    order = []
    for s in range(m):
        if visited[s]:
            continue
        st = [(s, iter(succ[s]))]
        visited[s] = True
        while st:
            u, it = st[-1]
            adv = False
            for w in it:
                if not visited[w]:
                    visited[w] = True
                    st.append((w, iter(succ[w])))
                    adv = True
                    break
            if not adv:
                order.append(u)
                st.pop()
    pred = [[] for _ in range(m)]
    for u in range(m):
        for w in succ[u]:
            pred[w].append(u)
    comp = [-1] * m
    k = 0
    for u in reversed(order):
        if comp[u] != -1:
            continue
        st = [u]; comp[u] = k
        while st:
            x = st.pop()
            for y in pred[x]:
                if comp[y] == -1:
                    comp[y] = k
                    st.append(y)
        k += 1
    cadj = [set() for _ in range(k)]
    for u in range(m):
        for w in succ[u]:
            if comp[w] != comp[u]:
                cadj[comp[u]].add(comp[w])
    indeg = [0] * k
    for u in range(k):
        for w in cadj[u]:
            indeg[w] += 1
    topo = [u for u in range(k) if indeg[u] == 0]
    i = 0
    while i < len(topo):
        u = topo[i]; i += 1
        for w in cadj[u]:
            indeg[w] -= 1
            if indeg[w] == 0:
                topo.append(w)
    reach = [0] * k
    for u in reversed(topo):
        r = 1 << u
        for w in cadj[u]:
            r |= reach[w]
        reach[u] = r
    adjL = []
    for u in range(k):
        r = reach[u] & ~(1 << u)
        lst = []
        while r:
            b = r & (-r); lst.append(b.bit_length() - 1); r ^= b
        adjL.append(lst)
    matchR = [-1] * k
    def aug(u, vis):
        for v in adjL[u]:
            if vis[v]:
                continue
            vis[v] = True
            if matchR[v] == -1 or aug(matchR[v], vis):
                matchR[v] = u
                return True
        return False
    for u in range(k):
        aug(u, [False] * k)
    nxt = {}
    targets = set()
    for v, u in enumerate(matchR):
        if u != -1:
            nxt[u] = v
            targets.add(v)
    starts = [u for u in range(k) if u not in targets]
    comp_edges = {}
    for i in range(m):
        comp_edges.setdefault(comp[i], []).append(i)
    strings = []
    for s in starts:
        seq = []
        chain = []
        u = s
        while True:
            chain.append(u)
            if u not in nxt:
                break
            u = nxt[u]
        for ci, c in enumerate(chain):
            es = comp_edges[c]
            if ci == 0:
                # closed walk over comp starting anywhere
                full = [es[0]]
                used = {es[0]}
                ok = True
                for a, b in zip(es, es[1:] + [es[0]]):
                    p = path_lg(a, b)
                    if p is None:
                        ok = False
                        break
                    for e in p[1:]:
                        full.append(e)
                if not ok:
                    return None
                # full is a closed walk starting/ending with es[0]; drop last repeat
                seq.extend(full[:-1])
            else:
                # enter comp c from current head letter
                head = edges[seq[-1]][1]
                entry = None
                for cand in by_tail[head]:
                    if comp[cand] == c:
                        entry = cand
                        break
                if entry is None:
                    return None
                p = path_lg(seq[-1], entry)
                if p is None:
                    return None
                seq.extend(p[1:])
