"""
Solution implementation.

Implement the function below to pass all tests.
"""

from typing import List, Tuple
from bisect import bisect_right


def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to move from square 1 to square N by repeatedly jumping.

    There are N squares arranged in a row, labeled 1 to N. You start at square 1 and want to reach square N.
    In each move, if you're at square x, you can jump to square x + i where:
    - a <= i <= b
    - x + i <= n
    - square x + i is not in any of the bad intervals

    A square j is bad if there exists some interval (l_i, r_i) such that l_i <= j <= r_i.

    Args:
        n: The number of squares (2 <= n <= 10^12)
        m: The number of bad intervals (0 <= m <= 2*10^4)
        a: The minimum jump size (1 <= a <= b <= 20)
        b: The maximum jump size
        bad_intervals: List of tuples (l_i, r_i) representing bad intervals.
                      The intervals are sorted and non-overlapping.

    Returns:
        True if it's possible to reach square n from square 1, False otherwise.
    """
    if n <= 1:
        return True

    # ---- normalize bad intervals into merged, sorted "blocks" clipped to [1, n]
    ivs = []
    for (l, r) in bad_intervals:
        l2, r2 = max(l, 1), min(r, n)
        if l2 <= r2:
            ivs.append((l2, r2))
    ivs.sort()
    blocks = []
    for (l, r) in ivs:
        if blocks and l <= blocks[-1][1] + 1:
            if r > blocks[-1][1]:
                blocks[-1] = (blocks[-1][0], r)
        else:
            blocks.append((l, r))
    starts = [bl for (bl, br) in blocks]

    def is_bad(x):
        i = bisect_right(starts, x) - 1
        return i >= 0 and blocks[i][1] >= x

    if is_bad(1):
        return False
    if is_bad(n):
        return False

    # ---- special case: fixed jump length (a == b): the path is forced
    if a == b:
        J = a
        if (n - 1) % J != 0:
            return False
        for (L, R) in blocks:
            klo = (L - 1 + J - 1) // J      # ceil((L-1)/J)
            khi = (R - 1) // J              # floor((R-1)/J)
            if klo <= khi:
                return False                # chain square inside this block
        return True

    # ---- general case (b > a): interval-based sweep over bad blocks
    def merge_sorted(iv):
        res = []
        for (l, r) in sorted(iv):
            if r < l:
                continue
            if res and l <= res[-1][1] + 1:
                if r > res[-1][1]:
                    res[-1] = (res[-1][0], r)
            else:
                res.append((l, r))
        return res

    def intersect(iv, lo, hi):
        res = []
        for (l, r) in iv:
            l2, r2 = max(l, lo), min(r, hi)
            if l2 <= r2:
                res.append((l2, r2))
        return res

    def subtract_blocks(iv):
        # subtract all bad blocks from sorted disjoint intervals
        res = []
        for (l, r) in iv:
            cur = l
            i = bisect_right(starts, cur) - 1
            if i < 0:
                i = 0
            while i < len(blocks):
                bl, br = blocks[i]
                if br < cur:
                    i += 1
                    continue
                if bl > r:
                    break
                if bl > cur:
                    res.append((cur, min(bl - 1, r)))
                cur = br + 1
                if cur > r:
                    break
                i += 1
            if cur <= r:
                res.append((cur, r))
        return res

    def cone(p, q, cap):
        # exact closure of reachable interval [p, q] inside a clean region [p, cap]
        res = []
        if p > cap:
            return res
        length = q - p + 1
        d = b - a
        t_star = (a - length + d - 1) // d
        if t_star < 0:
            t_star = 0
        t = 0
        while t < t_star:
            l, r = p + t * a, q + t * b
            if l > cap:
                break
            res.append((l, r if r < cap else cap))
            t += 1
        l = p + t_star * a
        if l <= cap:
            res.append((l, cap))
        return res

    def contains(iv, x):
        i = bisect_right([l for (l, r) in iv], x) - 1
        return i >= 0 and iv[i][1] >= x

    alive = [(1, 1)]   # reachable intervals that can still grow (in clean gap after last resolved block)
    dead = []          # reachable intervals that are fully resolved (below last resolved block)

    for (L, R) in blocks:
        cap = L - 1
        below_alive = [(p, q) for (p, q) in alive if q <= R]
        passed = len(below_alive) < len(alive)

        # closure of everything reachable at or before cap
        below = list(dead)
        for (p, q) in below_alive:
            below.extend(cone(p, q, cap))
        below = merge_sorted(below)

        if n <= cap:
            return contains(below, n)

        if not passed:
            # need to cross block [L, R]
            if R - L + 1 >= b:
                return False        # no pad can jump over a block of length >= b
            pads = intersect(below, R + 1 - b, L - 1)
            if not pads:
                return False
            land = [(rs + a, re + b) for (rs, re) in pads]
            land = intersect(land, R + 1, n)
            land = subtract_blocks(land)
            if not land:
                return False
            alive = land
        else:
            # block already jumped over; keep only pieces beyond it alive
            alive = [(p, q) for (p, q) in alive if q > R]

        # keep only the part of the resolved region that future pad windows can still reach
        dead = intersect(below, R + 2 - b, L - 1)

    # final closure up to n
    below = list(dead)
    for (p, q) in alive:
        below.extend(cone(p, q, n))
    below = merge_sorted(below)
    return contains(below, n)
