from functools import lru_cache

LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def winner(grid):
    vals = tuple(grid[i][j] for i in range(3) for j in range(3))
    total = sum(vals)

    @lru_cache(maxsize=None)
    def f(red, blue):
        for a,b,c in LINES:
            if red & (1<<a) and red & (1<<b) and red & (1<<c):
                return 1
            if blue & (1<<a) and blue & (1<<b) and blue & (1<<c):
                return -1
        if red | blue == 511:
            ts = sum(vals[i] for i in range(9) if red>>i & 1)
            return 1 if ts*2 > total else -1
        t_turn = ((red|blue).bit_count() % 2 == 0)
        best = -2 if t_turn else 2
        for i in range(9):
            if not ((red|blue)>>i) & 1:
                if t_turn:
                    v = f(red | (1<<i), blue)
                    if v > best: best = v
                else:
                    v = f(red, blue | (1<<i))
                    if v < best: best = v
        return best

    return "Takahashi" if f(0,0) == 1 else "Aoki"

if __name__ == "__main__":
    import re, ast
    src = open("test_solution.py").read()
    asserts = re.findall(r"assert candidate\((.*?)\) == '(\w+)'", src)
    fails = 0
    for idx,(g,exp) in enumerate(asserts):
        grid = ast.literal_eval(g)
        got = winner(grid)
        ok = got == exp
        if not ok:
            fails += 1
            print(idx, exp, got, g)
    print("total", len(asserts), "fails", fails)
